if (cls.confidence < threshold) reasons.push('low confidence ' + cls.confidence + ' < ' + threshold);
if (V2) {
  if (injection) reasons.push('possible prompt injection in email');
  if (cls.sentiment === 'angry') reasons.push('angry customer');
  if (cls.intent !== 'other') {
