  // threshold alone did not catch it. A customer chasing an order we cannot find always goes to a person.
  if (V2 && cls.intent === 'order_status' && ctx.lookup.status === 'no_match') reasons.push('customer is chasing an order but none was found for this sender');
} else {
  if (cls.other_category === 'partnership') notes.push('forward to partnerships@kesarandco.example (FAQ section 9)');
  if (cls.other_category !== 'none') notes.push('category: ' + cls.other_category);
}

// Rough size estimate only (characters / 4). Real token counts are not exposed by the agent node.
const approxTokens = Math.round(
  ((ctx.classifier_system || '').length + (ctx.classifier_user || '').length + (ctx.cls_raw || '').length + (ctx.cls_repair_raw || '').length +
    (isReplyBranch ? (ctx.agent_system || '').length + (ctx.agent_user || '').length + toolText.length + draft.length : 0)) / 4
);

if (ctx.decision.explanation) notes.unshift(ctx.decision.code + ': ' + ctx.decision.explanation);
if (cls.intent !== 'other') notes.push('order lookup: ' + ctx.lookup.status + ' (by ' + ctx.lookup.method.replace('_', ' ') + ')');
(ctx.cls_notes || []).forEach((n) => notes.push(n));
if (ctx.cls_attempts > 1) error = (error ? error + ' | ' : '') + 'classifier first output invalid (' + (ctx.cls_first_errors || []).join('; ') + '), ' + (ctx.cls_fallback ? 'repair call also failed, fallback used' : 'fixed by one repair call');

const out = Object.assign({}, ctx, {
  reply_draft: draft,
  needs_human: reasons.length > 0,
  needs_human_reasons: reasons,
  action_base: isReplyBranch ? 'draft_reply' : 'log_only',
  tools_called: toolsCalled,
  approx_tokens: approxTokens,
  final_notes: notes,
  final_error: error,
});
// keep the logged item small
delete out.agent_system;
delete out.classifier_system;

return [{ json: out }];

// Node: "Ticket Upsert Logic"
// Input: every row of the Tickets tab. Output: ONE row for "Append or Update Row" (matched on ticket_id).
// An open ticket for the same order is reused (email ID + note appended) instead of creating a duplicate.
const ctx = $('Guardrails & Finalize').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.ticket_id);

const email = ctx.email;
const cls = ctx.classification;
const now = new Date().toISOString();

// Use the order ID the customer wrote even when we could not verify it, so follow-ups still group together.
const orderId = ctx.lookup.order_id || cls.order_id || '';
const isOpen = (r) => String(r.status || '').trim().toLowerCase() !== 'closed';
const sameCase = (r) =>
  orderId
    ? String(r.order_id || '').trim().toUpperCase() === orderId
    : !String(r.order_id || '').trim() && String(r.customer_email || '').trim().toLowerCase() === email.from_email;

const existing = rows.find((r) => isOpen(r) && sameCase(r));

const note =
  '[' + now.slice(0, 16).replace('T', ' ') + 'Z ' + email.id + '] ' + cls.summary +
  ' | ' + ctx.decision.code +
  (ctx.lookup.status !== 'found' ? ' | order ' + ctx.lookup.status : '') +
  (email.attachments.length ? ' | attachments: ' + email.attachments.join(', ') : '') +
  (ctx.needs_human ? ' | needs human: ' + ctx.needs_human_reasons.join('; ') : '');

const RANK = { Low: 1, Medium: 2, High: 3 };
let row;
if (existing) {
  const ids = String(existing.email_ids || '').split(/[,\s]+/).filter(Boolean);
  const already = ids.includes(email.id);
  if (!already) ids.push(email.id);
  const oldP = String(existing.priority || 'Medium');
  row = {
    ticket_id: String(existing.ticket_id),
    created_at: String(existing.created_at || ''),
    updated_at: now,
    order_id: String(existing.order_id || ''),
    customer_email: String(existing.customer_email || ''),
    email_ids: ids.join(', '),
    intent: String(existing.intent || cls.intent),
    priority: (RANK[ctx.ticket_priority] || 0) > (RANK[oldP] || 0) ? ctx.ticket_priority : oldP,
    status: String(existing.status || 'Open'),
    summary: String(existing.summary || cls.summary),
    notes: already ? String(existing.notes || '') : (existing.notes ? String(existing.notes) + '\n' : '') + note,
  };
} else {
  row = {
    ticket_id: 'TKT-' + (orderId ? orderId.replace('KC-', '') : 'NOORDER') + '-' + email.id,
    created_at: now,
    updated_at: now,
    order_id: orderId,
    customer_email: email.from_email,
    email_ids: email.id,
    intent: cls.intent,
    priority: ctx.ticket_priority,
    status: 'Open',
    summary: cls.summary,
    notes: note,
  };
}

return [{ json: row }];

// Node: "Build Audit Row"
// One row per email for the Audit Log tab. First 18 columns are the assignment template; the rest are extras.
const ctx = $('Guardrails & Finalize').first().json;
const email = ctx.email;
const cls = ctx.classification;

let ticketId = '';
let action = ctx.action_base;
if (ctx.needs_ticket && $('Ticket Upsert Logic').isExecuted) {
  const t = $('Ticket Upsert Logic').first().json;
  ticketId = t.ticket_id;
  action = (t.created_at === t.updated_at ? 'ticket_created' : 'ticket_updated') + ' + draft_reply';
}
if (ctx.needs_human) action += ' (needs human)';

return [
  {
    json: {
      email_id: email.id,
      received_at: email.received_at,
      from_email: email.from_email,
      intent: cls.intent,
      secondary_intent: cls.secondary_intent || '',
      order_id: cls.order_id || ctx.lookup.order_id || '',
      language: cls.language,
      sentiment: cls.sentiment,
      confidence: cls.confidence,
      order_found: cls.intent === 'other' && !cls.order_id ? 'n/a' : ctx.lookup.status === 'found' ? 'yes' : 'no (' + ctx.lookup.status + ')',
      action_taken: action,
      needs_human: ctx.needs_human ? 'TRUE' : 'FALSE',
      ticket_id: ticketId,
      reply_draft: ctx.reply_draft,
      prompt_version: ctx.config.prompt_version,
      processed_at: new Date().toISOString(),
      error: ctx.final_error,
      notes: ctx.final_notes.join(' | '),
      // extras
      needs_human_reason: ctx.needs_human_reasons.join(' | '),
      decision_code: ctx.decision.code,
      tools_called: ctx.tools_called.join(', '),
      json_valid_first_try: ctx.json_valid_first_try ? 'TRUE' : 'FALSE',
      approx_tokens: ctx.approx_tokens,
      summary: cls.summary,
    },
  },
];
